double clamp(double x,double lo,double hi){return std::max(lo,std::min(hi,x));}
double sq(double x){return x*x;}
constexpr int kBaseDraws=700;
constexpr int kVerificationDraws=2800;
constexpr double kSectorGridStep=25.0;
constexpr std::size_t kSectorFinalists=8;

struct SectorProfile{const char*code;const char*name;double trade,import,jobs,cyclical;};
constexpr SectorProfile sector_profiles[]={
{"11","Agriculture, forestry, fishing & hunting",.82,.42,.72,.65},{"21","Mining, quarrying, oil & gas",.88,.18,.32,.75},
{"22","Utilities",.16,.10,.25,.25},{"23","Construction",.18,.28,.82,.88},{"31-33","Manufacturing",.94,.76,.68,.92},
{"42","Wholesale trade",.68,.58,.64,.74},{"44-45","Retail trade",.30,.72,.88,.62},{"48-49","Transportation & warehousing",.72,.48,.70,.86},
{"51","Information & cultural industries",.34,.30,.48,.44},{"52","Finance & insurance",.22,.20,.34,.55},
{"53","Real estate, rental & leasing",.10,.12,.30,.78},{"54","Professional, scientific & technical services",.38,.26,.58,.48},
{"55","Management of companies & enterprises",.20,.18,.24,.40},{"56","Administrative, support & waste services",.28,.24,.86,.72},
{"61","Educational services",.08,.10,.82,.18},{"62","Health care & social assistance",.06,.14,.94,.16},
{"71","Arts, entertainment & recreation",.14,.16,.88,.68},{"72","Accommodation & food services",.18,.52,.96,.82},
{"81","Other services (except public administration)",.16,.30,.90,.58},{"91","Public administration",.04,.08,.62,.12}};

struct SectorUtility{double canada=0,us=0;SectorImpact impact;};
std::vector<double> coverage_levels(double current,double ceiling){
  const double start=clamp(current,0.0,100.0),cap=clamp(ceiling/100.0,0.0,1.0);
  std::vector<double> levels;for(double f:{0.0,.25,.50,.75,1.0})levels.push_back(start*(1.0-cap*f));
  std::sort(levels.begin(),levels.end());levels.erase(std::unique(levels.begin(),levels.end(),[](double a,double b){return std::abs(a-b)<1e-9;}),levels.end());return levels;
}

SectorUtility sector_utility(const Economy&e,const Scenario&pcy,std::size_t sector,double us_coverage,double ca_coverage){
  const auto&p=sector_profiles[sector];const double deesc=clamp(pcy.negotiated_relief/100.0,0.0,1.0);
  const double div=clamp(pcy.diversification+e.trade_diversification,0.0,.75),uc=clamp(us_coverage/100.0,0.0,1.0),cc=clamp(ca_coverage/100.0,0.0,1.0);
  const double ut=e.us_tariff_canada*(1.0-deesc)/100.0*uc,ct=e.canada_retaliatory_tariff*(1.0-deesc)/100.0*cc;
  const double supply=pcy.productive_share*pcy.fiscal_impulse*(.16+.12*p.cyclical),ca_shock=ut*p.trade*(.72-.28*div)+e.border_friction/100.0*p.trade*.18;
  const double us_shock=ct*p.import*.46+ut*p.import*.12,us_protection=ut*p.trade*.24*(1.0-.5*uc);
  SectorUtility o;o.impact.code=p.code;o.impact.name=p.name;o.impact.exposure=100.0*p.trade;
  o.impact.canada_output=100.0*(-ca_shock+supply+pcy.targeted_relief*.10*p.jobs);o.impact.us_output=100.0*(-us_shock+us_protection+deesc*.012*p.trade);
  o.impact.canada_jobs=o.impact.canada_output*(.30+.42*p.jobs);o.impact.us_jobs=o.impact.us_output*(.28+.38*p.jobs);
  o.impact.canada_prices=100.0*(ct*p.import*.30+ut*p.import*.05-supply*.10);o.impact.us_prices=100.0*(ut*p.import*.24+ct*p.import*.10);
  const double pw=.65+.70*clamp(e.risk_aversion/100.0,0.0,1.0)+.18*std::max(0.0,(e.inflation+e.us_inflation)/2.0-2.0);
  const double cjw=.45+.08*std::max(0.0,e.unemployment-5.0),ujw=.45+.08*std::max(0.0,4.5-e.us_growth),lev=100.0*ct*p.trade*.16*(1.0-.65*cc);
  o.canada=p.trade*(o.impact.canada_output+cjw*o.impact.canada_jobs-pw*o.impact.canada_prices+lev);
  o.us=p.import*(o.impact.us_output+ujw*o.impact.us_jobs-pw*o.impact.us_prices);return o;
}
void add_sector_impacts(Scenario&s,const Economy&e){s.sectors.clear();s.sectors.reserve(std::size(sector_profiles));for(std::size_t i=0;i<std::size(sector_profiles);++i)s.sectors.push_back(sector_utility(e,s,i,e.us_sector_coverage[i],e.canada_sector_coverage[i]).impact);}

struct CoverageCandidate{double canada_raw=0,us_raw=0,canada_score=0,us_score=0,objective=-1e100;std::array<double,20>us_coverage{},canada_coverage{};};
struct SectorSearch{std::vector<CoverageCandidate>finalists;int candidates_examined=0,pareto_frontier_size=0;double canada_min=0,canada_max=0,us_min=0,us_max=0,baseline_canada_score=0,baseline_us_score=0;};
double norm(double v,double lo,double hi){return 100.0*(v-lo)/std::max(1e-9,hi-lo);}

SectorSearch search_sector_frontier(const Economy&e,const Scenario&pcy){
  SectorSearch s;std::vector<CoverageCandidate>frontier(1);double cmin=0,cmax=0,umin=0,umax=0,basec=0,baseu=0;
  for(std::size_t sector=0;sector<std::size(sector_profiles);++sector){
    const auto ul=coverage_levels(e.us_sector_coverage[sector],e.cooperation_ceiling),cl=coverage_levels(e.canada_sector_coverage[sector],e.cooperation_ceiling);
    struct Option{double uc,cc,ca,us;};std::vector<Option>opts;double scmin=std::numeric_limits<double>::infinity(),scmax=-scmin,sumin=scmin,sumax=-scmin;
    for(double uc:ul)for(double cc:cl){auto v=sector_utility(e,pcy,sector,uc,cc);opts.push_back({uc,cc,v.canada,v.us});scmin=std::min(scmin,v.canada);scmax=std::max(scmax,v.canada);sumin=std::min(sumin,v.us);sumax=std::max(sumax,v.us);}
    cmin+=scmin;cmax+=scmax;umin+=sumin;umax+=sumax;auto b=sector_utility(e,pcy,sector,e.us_sector_coverage[sector],e.canada_sector_coverage[sector]);basec+=b.canada;baseu+=b.us;
    std::vector<CoverageCandidate>x;x.reserve(frontier.size()*opts.size());for(const auto&p:frontier)for(const auto&o:opts){auto c=p;c.canada_raw+=o.ca;c.us_raw+=o.us;c.us_coverage[sector]=o.uc;c.canada_coverage[sector]=o.cc;x.push_back(std::move(c));}s.candidates_examined+=static_cast<int>(x.size());
    std::sort(x.begin(),x.end(),[](const auto&a,const auto&b){if(std::abs(a.canada_raw-b.canada_raw)>1e-9)return a.canada_raw>b.canada_raw;return a.us_raw>b.us_raw;});frontier.clear();double bestu=-std::numeric_limits<double>::infinity();for(auto&c:x)if(c.us_raw>bestu+1e-9){bestu=c.us_raw;frontier.push_back(std::move(c));}
  }
  s.canada_min=cmin;s.canada_max=cmax;s.us_min=umin;s.us_max=umax;s.baseline_canada_score=norm(basec,cmin,cmax);s.baseline_us_score=norm(baseu,umin,umax);s.pareto_frontier_size=static_cast<int>(frontier.size());
  const double cw=clamp(e.canada_priority,1.0,100.0),uw=clamp(e.us_priority,1.0,100.0),tw=cw+uw;std::vector<CoverageCandidate>ww;
  for(auto&c:frontier){c.canada_score=norm(c.canada_raw,cmin,cmax);c.us_score=norm(c.us_raw,umin,umax);if(c.canada_score+1e-9<s.baseline_canada_score||c.us_score+1e-9<s.baseline_us_score)continue;double n=std::exp((cw*std::log(std::max(.01,c.canada_score))+uw*std::log(std::max(.01,c.us_score)))/tw),fair=std::min(c.canada_score,c.us_score),sum=0;for(std::size_t i=0;i<20;++i)sum+=c.us_coverage[i]+c.canada_coverage[i];c.objective=.72*n+.28*fair-.00002*sum;ww.push_back(c);}
  if(ww.empty()){CoverageCandidate b;b.canada_raw=basec;b.us_raw=baseu;b.canada_score=s.baseline_canada_score;b.us_score=s.baseline_us_score;b.us_coverage=e.us_sector_coverage;b.canada_coverage=e.canada_sector_coverage;b.objective=std::min(b.canada_score,b.us_score);ww.push_back(b);}
  std::sort(ww.begin(),ww.end(),[](const auto&a,const auto&b){return a.objective>b.objective;});const auto keep=std::min<std::size_t>(kSectorFinalists,ww.size());s.finalists.assign(ww.begin(),ww.begin()+keep);return s;
}

Scenario simulate(const Economy&e,std::string id,std::string name,std::string description,double move,double fiscal,double productive,double deesc,double relief,double div,std::uint64_t seed,int draws=kBaseDraws){
  Scenario s;s.id=std::move(id);s.name=std::move(name);s.description=std::move(description);s.first_move_bp=move;s.fiscal_impulse=fiscal;s.productive_share=productive;s.negotiated_relief=100.0*deesc;s.targeted_relief=relief;s.diversification=div;s.applied_us_sector_coverage=e.us_sector_coverage;s.applied_canada_sector_coverage=e.canada_sector_coverage;
  std::mt19937_64 rng(seed);std::normal_distribution<double>shock(0.0,1.0);double is=0,gs=0,ugs=0,us=0,ds=0,hs=0,cs=0,rs=0,xs=0,uxs=0,recs=0;std::array<double,12>rp{},ip{},gp{},ugp{},dp{},cp{},xp{},uxp{};std::vector<double>td,ti;td.reserve(draws);ti.reserve(draws);
  double ubc=0,cbc=0,cw=0,uw=0;for(std::size_t i=0;i<std::size(sector_profiles);++i){cw+=sector_profiles[i].trade;uw+=sector_profiles[i].import;ubc+=sector_profiles[i].trade*clamp(e.us_sector_coverage[i]/100.0,0.0,1.0);cbc+=sector_profiles[i].import*clamp(e.canada_sector_coverage[i]/100.0,0.0,1.0);}ubc/=std::max(1e-9,cw);cbc/=std::max(1e-9,uw);
  for(int d=0;d<draws;++d){double rate=e.policy_rate,inf=e.core_inflation,gap=e.output_gap,u=e.unemployment,debt=e.federal_debt_gdp,housing=e.housing_gap,xc=0,uxc=0,cost=e.inflation;bool rec=false;for(int q=0;q<12;++q){double coord=productive*fiscal,ut=std::max(0.0,e.us_tariff_canada*ubc*(1.0-deesc)),ct=std::max(0.0,e.canada_retaliatory_tariff*cbc*(1.0-deesc));double exposed=e.exports_to_us_share/100.0*(1.0-clamp(div+e.trade_diversification,0.0,.75)),drag=exposed*e.exports_gdp/100.0*e.trade_elasticity*(ut+e.border_friction)/100.0,udrag=e.imports_from_us_share/100.0*e.trade_elasticity*(ct+.45*e.border_friction)/100.0,imp=e.imports_from_us_share/100.0*e.import_content_consumption/100.0*ct;double rt=clamp(2.5+.75*(inf-2.0)+.25*gap,.25,7.0);if(q==0)rate=clamp(rate+move/100.0,0.0,8.0);else rate=clamp(rate+clamp(rt-rate,-.25,.25),0.0,8.0);double demand=fiscal*(1.0-productive)*.36-(rate-2.5)*.18,supply=coord*.22+e.productivity_growth*.035;xc=-100.0*drag+.35*(e.us_growth-2.0)+2.0*div+shock(rng)*.35;uxc=-100.0*udrag+.30*(e.gdp_growth-1.5)+1.5*deesc+shock(rng)*.30;gap=.72*gap+demand-drag+.08*(e.global_growth-2.7)+shock(rng)*.16;double fx=(e.usdcad-1.34)*.35;inf=.68*inf+.32*e.inflation_expectations+.12*gap+fx-supply+.022*imp-.018*(e.oil_price-75.0)+shock(rng)*.11;double growth=clamp(1.75+gap-.18*e.credit_spread+coord*.24+shock(rng)*.25,-3.0,5.5),ugrowth=clamp(e.us_growth+.16*coord+.28*deesc-.010*ut-.014*ct-.04*e.border_friction+shock(rng)*.18,-3.0,5.5);u=clamp(u-.10*(growth-1.7)+shock(rng)*.035,3.5,11.0);housing=clamp(.78*housing-1.15*(rate-2.5)+.08*(e.population_growth-1.2)+shock(rng)*.5,-15.0,30.0);double rcost=relief+e.tariff_relief;debt+=(-e.fiscal_balance_gdp+fiscal*.8+rcost*.55+.045*(rate-2.5)*debt-.18*growth)/4.0;cost=.56*inf+.22*std::max(0.0,housing/10.0)+.14*std::max(0.0,e.wage_growth-growth)+.08*imp;rec=rec||growth<0;rp[q]+=rate;ip[q]+=inf;gp[q]+=growth;ugp[q]+=ugrowth;dp[q]+=debt;cp[q]+=cost;xp[q]+=xc;uxp[q]+=uxc;if(q==11){is+=inf;gs+=growth;ugs+=ugrowth;us+=u;ds+=debt;hs+=housing;cs+=cost;rs+=growth-cost+relief*.15;xs+=xc;uxs+=uxc;td.push_back(debt);ti.push_back(inf);}}if(rec)recs++;}
  for(int q=0;q<12;++q){s.rates[q]=rp[q]/draws;s.inflation_path[q]=ip[q]/draws;s.growth_path[q]=gp[q]/draws;s.us_growth_path[q]=ugp[q]/draws;s.debt_path[q]=dp[q]/draws;s.cost_path[q]=cp[q]/draws;s.export_path[q]=xp[q]/draws;s.us_export_path[q]=uxp[q]/draws;}s.inflation=is/draws;s.growth=gs/draws;s.us_growth=ugs/draws;s.unemployment=us/draws;s.bilateral_growth_floor=std::min(*std::min_element(s.growth_path.begin(),s.growth_path.end()),*std::min_element(s.us_growth_path.begin(),s.us_growth_path.end()));s.sustained_bilateral_growth=s.bilateral_growth_floor+1e-9>=e.minimum_bilateral_growth;s.debt_gdp=ds/draws;s.housing_gap=hs/draws;s.recession_risk=100.0*recs/draws;s.cost_of_living=cs/draws;s.real_income_growth=rs/draws;s.export_change=xs/draws;s.us_export_change=uxs/draws;
  double eur=std::max(0.0,e.us_tariff_canada*ubc*(1.0-deesc))/100.0,ecr=std::max(0.0,e.canada_retaliatory_tariff*cbc*(1.0-deesc))/100.0,cae=e.canada_exports_to_us_cad*std::max(.05,1.0-e.trade_elasticity*eur),cai=e.canada_imports_from_us_cad*std::max(.05,1.0-e.trade_elasticity*ecr);s.us_export_expansion_usd=0;s.canada_export_redirection_cad=0;s.us_tariff_revenue_cad=eur*cae;s.us_tariff_revenue_usd=s.us_tariff_revenue_cad/e.usdcad;s.canada_tariff_revenue_cad=ecr*cai;s.canada_tariff_revenue_usd=s.canada_tariff_revenue_cad/e.usdcad;s.canada_trade_balance_cad=cae-cai;s.us_trade_balance_usd=-s.canada_trade_balance_cad/e.usdcad;s.trade_balance_gap_usd=std::abs(s.us_trade_balance_usd);double ig=std::abs(e.canada_exports_to_us_cad-e.canada_imports_from_us_cad)/e.usdcad;s.trade_balance_progress=100.0*(1.0-s.trade_balance_gap_usd/std::max(.001,ig));s.zero_trade_deficit=s.trade_balance_gap_usd<.05;
  std::sort(td.begin(),td.end());std::sort(ti.begin(),ti.end());s.debt_stress_p90=td[static_cast<std::size_t>(draws*9/10)];s.inflation_stress_p90=ti[static_cast<std::size_t>(draws*9/10)];double ml=3.8*sq(s.inflation-2.0)+1.2*sq(std::max(0.0,s.unemployment-5.8))+.7*sq(std::min(0.0,s.growth))+.018*s.recession_risk,fl=.32*sq(std::max(0.0,s.debt_gdp-e.federal_debt_gdp))+.7*sq(std::min(0.0,s.growth))+.8*sq(std::max(0.0,s.unemployment-6.0))+.012*sq(s.housing_gap);s.boc_score=100.0/(1.0+ml);s.federal_score=100.0/(1.0+fl);double uip=std::max(0.0,e.us_inflation-2.0+e.us_tariff_canada*ubc*.025),ul=.55*sq(std::max(0.0,-s.us_export_change))+.8*sq(uip)+.55*sq(std::max(0.0,1.8-s.us_growth))+.25*sq(e.canada_retaliatory_tariff*cbc*(1.0-deesc));s.us_score=100.0/(1.0+ul);double ca=std::sqrt(std::max(.01,s.boc_score)*std::max(.01,s.federal_score)),floor=std::min(ca,s.us_score),cwt=clamp(e.canada_priority,1.0,100.0),uwt=clamp(e.us_priority,1.0,100.0),tot=cwt+uwt,nash=std::exp((cwt*std::log(std::max(.01,ca))+uwt*std::log(std::max(.01,s.us_score)))/tot),safety=clamp(e.risk_aversion/100.0,0.0,1.0),tail=safety*(.10*s.recession_risk+.35*std::max(0.0,s.inflation_stress_p90-3.0)+.08*std::max(0.0,s.debt_stress_p90-e.federal_debt_gdp-5.0));s.score=(.78-.18*safety)*nash+(.22+.18*safety)*floor-tail;add_sector_impacts(s,e);return s;
}

double deal_score(const Scenario&s,const Economy&e,bool enforce=true){if(enforce&&s.bilateral_growth_floor+1e-9<e.minimum_bilateral_growth)return-1e100;double ca=std::sqrt(std::max(.01,s.boc_score)*std::max(.01,s.federal_score)),cw=clamp(e.canada_priority,1.0,100.0),uw=clamp(e.us_priority,1.0,100.0),tot=cw+uw,nash=std::exp((cw*std::log(std::max(.01,ca))+uw*std::log(std::max(.01,s.us_score)))/tot),floor=std::min(ca,s.us_score),safety=clamp(e.risk_aversion/100.0,0.0,1.0),tail=safety*(.10*s.recession_risk+.35*std::max(0.0,s.inflation_stress_p90-3.0)+.08*std::max(0.0,s.debt_stress_p90-e.federal_debt_gdp-5.0)),sf=std::numeric_limits<double>::infinity(),sum=0;std::size_t n=0;for(const auto&x:s.sectors){std::array<double,6>m{x.canada_output,x.canada_jobs,-x.canada_prices,x.us_output,x.us_jobs,-x.us_prices};for(double v:m){sf=std::min(sf,v);sum+=v;++n;}}return .66*nash+.26*floor-.05*tail+.055*sf+.018*(n?sum/static_cast<double>(n):0.0);}
double min_sector_metric(const Scenario&s){double o=std::numeric_limits<double>::infinity();for(const auto&x:s.sectors){o=std::min(o,x.canada_output);o=std::min(o,x.canada_jobs);o=std::min(o,-x.canada_prices);o=std::min(o,x.us_output);o=std::min(o,x.us_jobs);o=std::min(o,-x.us_prices);}return std::isfinite(o)?o:0.0;}
struct ScenarioMeta{std::string id;int candidates_examined=0,pareto_size=0,finalists=0;double sector_ca_score=0,sector_us_score=0,baseline_ca_score=0,baseline_us_score=0;};
const ScenarioMeta*find_meta(const std::vector<ScenarioMeta>&m,const std::string&id){for(const auto&x:m)if(x.id==id)return&x;return nullptr;}
void fill_sector_display_metrics(const Economy&e,const Scenario&p,WinWinRecommendation&r){for(std::size_t i=0;i<std::size(sector_profiles);++i){auto ul=coverage_levels(e.us_sector_coverage[i],e.cooperation_ceiling),cl=coverage_levels(e.canada_sector_coverage[i],e.cooperation_ceiling);double cmin=std::numeric_limits<double>::infinity(),cmax=-cmin,umin=cmin,umax=-cmin;for(double uc:ul)for(double cc:cl){auto v=sector_utility(e,p,i,uc,cc);cmin=std::min(cmin,v.canada);cmax=std::max(cmax,v.canada);umin=std::min(umin,v.us);umax=std::max(umax,v.us);}auto v=sector_utility(e,p,i,r.us_sector_coverage[i],r.canada_sector_coverage[i]);r.canada_sector_value[i]=norm(v.canada,cmin,cmax);r.us_sector_output[i]=norm(v.us,umin,umax);}}
std::string esc(const std::string&x){std::string o;for(char c:x){if(c=='"'||c=='\\')o+='\\';o+=c;}return o;}
template<std::size_t N>void array_json(std::ostringstream&o,const std::array<double,N>&a){o<<'[';for(std::size_t i=0;i<N;++i){if(i)o<<',';o<<a[i];}o<<']';}
